import {verifiedFetch} from '@github-ui/verified-fetch'
import type {PullsInboxMaxAge} from '../types/routes-types'

const DASHBOARD_PREFERENCES_PATH = '/dashboard/preferences'

export async function saveInboxMaxPrAge(maxPrAge: PullsInboxMaxAge): Promise<void> {
  const formData = new FormData()
  formData.set('pulls_inbox_max_pr_age', maxPrAge)

  const response = await verifiedFetch(DASHBOARD_PREFERENCES_PATH, {
    method: 'PUT',
    body: formData,
  })
  if (!response.ok) {
    throw new Error(`Failed to save preference: ${response.statusText}`)
  }
}
