import {useLocation, useNavigation, useSearchParams} from '@github-ui/react-router'
import type {Location} from '@github-ui/react-router'
import {Pagination} from '@primer/react'
import {ErrorBoundary} from '@github-ui/react-core/error-boundary'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {PullsList} from '@github-ui/shared-dashboard-lists/pulls/PullsList'
import {SharedDashboardBlankslate} from '@github-ui/shared-dashboard-lists/shared/SharedDashboardBlankslate'
import {SharedListLoadingSkeleton} from '@github-ui/shared-dashboard-lists/shared/SharedListLoadingSkeleton'

import {useEnrichedPulls} from '../hooks/use-enriched-pulls'
import {usePullsDashboardState} from '../hooks/use-pulls-dashboard-state'
import {addSortToQuery, getSortFromQuery} from '@github-ui/dashboard-sorting-dropdown/query'
import {usePullsDashboardSearch} from '../contexts/PullsDashboardSurfaceStateContext'
import {usePullsDashboardSurfaceLayoutState} from '../hooks/use-pulls-dashboard-surface-layout-state'
import {useUpdateCompactModeSetting} from '../hooks/use-update-compact-mode-setting'
import {useScreenReaderAnnouncements} from '../hooks/use-screen-reader-announcements'
import {DEFAULT_SORTING_KEY} from '../constants/pulls-sorting'
import {PULLS_SEARCH_PATH} from '../constants/routes'
import {addStateToQuery, getStateFromQuery} from '../helpers/open-closed-toggle'
import {
  addRepoFilterToQuery,
  addAuthorFilterToQuery,
  addLabelFilterToQuery,
  addAssigneeFilterToQuery,
} from '../helpers/query-filters'
function isSameLocation(a: Location, b: Location): boolean {
  return a.pathname === b.pathname && a.search === b.search
}

export function PullsDashboardSurfaceContentComponent() {
  const navigation = useNavigation()
  const location = useLocation()

  // From: https://github.com/github/github-ui/blob/48fbe572f28ce54e40331641e1edc91160edb4a3/packages/repos-finder/routes/ReposFinderPageFuture.tsx#L29-L38
  // We compare navigation.location (the pending destination) with the current location
  // to determine if we're navigating to a *different* page. Using navigation.state === 'loading'
  // alone isn't sufficient because it also returns true when re-clicking the same sidebar item
  // triggers a background refetch, which we don't want to show as a full page loading state.
  //
  // We also can't rely on `isLoading` from `useSuspenseRouteQuery` because the route query is
  // blocking - the component suspends until data is fetched, so by the time we have access to
  // the query result, the data is already loaded. This doesn't give us a chance to show the
  // skeleton during navigation. Instead, we detect navigation at this level before suspense kicks in.
  const isNavigating = Boolean(navigation.location && !isSameLocation(navigation.location, location))

  const [searchParams] = useSearchParams()
  const searchQuery = searchParams.has('q')
  const isOnSearchPageWithNoQuery = location.pathname === PULLS_SEARCH_PATH && !searchQuery

  if (isNavigating) {
    return <SharedListLoadingSkeleton dashboardType="pull-requests" numItems={5} />
  }

  return (
    <ErrorBoundary
      boundaryName="PullsDashboardContent"
      fallback={
        <div className="tmp-my-3">
          <SharedDashboardBlankslate dashboardType="pull-requests" variant="error" />
        </div>
      }
    >
      {isOnSearchPageWithNoQuery ? (
        <SharedDashboardBlankslate dashboardType="pull-requests" variant="emptySearch" />
      ) : (
        <PullsDashboardPageContent />
      )}
    </ErrorBoundary>
  )
}

function PullsDashboardPageContent() {
  const {pulls, pageInfo, isPending, error} = useEnrichedPulls()
  const {compactMode} = usePullsDashboardSurfaceLayoutState()
  const {currentPage, methods, isLoading} = usePullsDashboardState({results: pulls, pageInfo, error})
  const {fetchedQuery} = usePullsDashboardSearch()
  const isFetching = isLoading || !!isPending

  const {emptyListState} = useScreenReaderAnnouncements(
    'pull-requests',
    isFetching,
    currentPage,
    fetchedQuery,
    DEFAULT_SORTING_KEY,
    pageInfo.totalCount,
    pageInfo.totalPages,
  )

  const {updateCompactModeSetting} = useUpdateCompactModeSetting(compactMode, 'dashboard_surface_compact_mode')

  const handleFilterSelect = (type: 'repo' | 'author' | 'label' | 'assignee', value: string) => {
    let newQuery: string
    switch (type) {
      case 'repo':
        newQuery = addRepoFilterToQuery(fetchedQuery, value)
        break
      case 'author':
        newQuery = addAuthorFilterToQuery(fetchedQuery, value)
        break
      case 'label':
        newQuery = addLabelFilterToQuery(fetchedQuery, value)
        break
      case 'assignee':
        newQuery = addAssigneeFilterToQuery(fetchedQuery, value)
        break
      default: {
        const _exhaustive: never = type
        return _exhaustive
      }
    }
    methods.updateAndSubmitQuery(newQuery)
  }

  return (
    <>
      <div className="tmp-my-3">
        <div data-hpc>
          {error ? (
            <SharedDashboardBlankslate dashboardType="pull-requests" variant="error" />
          ) : (
            <>
              <PullsList
                pulls={pulls}
                pageInfo={pageInfo}
                compactMode={compactMode}
                onCompactModeChange={updateCompactModeSetting}
                onSortingItemSelect={sort => methods.updateAndSubmitQuery(addSortToQuery(fetchedQuery, sort))}
                onStateFilterSelect={state => methods.updateAndSubmitQuery(addStateToQuery(fetchedQuery, state))}
                sortingItemSelected={getSortFromQuery(fetchedQuery)}
                stateItemSelected={getStateFromQuery(fetchedQuery)}
                emptyListState={emptyListState}
                onFilterSelect={handleFilterSelect}
                isDeferredLoading={isPending}
                isAgentAttributionEnabled={isFeatureEnabled('agent_author_search_expansion_ui_pulls')}
              />
              {pageInfo.totalPages > 1 && (
                <Pagination
                  pageCount={pageInfo.totalPages}
                  currentPage={pageInfo.currentPage}
                  onPageChange={(e, page) => {
                    e.preventDefault()

                    methods.fetchResults({q: fetchedQuery, page})
                    window.scrollTo({top: 0})
                  }}
                />
              )}
            </>
          )}
        </div>
      </div>
    </>
  )
}
