import {createContext, use, useCallback, useMemo, useState} from 'react'
import {useLocation} from '@github-ui/react-router'
import {isOnInboxPath} from '../helpers/is-on-inbox'
import {queryMap} from '../helpers/query-resolver'
import type {ReactNode} from 'react'

import type {PullsDashboardLayoutPayload, PullsInboxMaxAge as PullsInboxMaxAgeType} from '../types/routes-types'
import {PullsInboxMaxAge} from '../types/routes-types'
import {useListResults} from '../hooks/use-list-results'

// Stable context: holds the (optimistically-updated) payload and its raw server source.
// Updates only on route load or when the user saves section preferences.
interface PullsDashboardPayloadContextValue {
  payload: PullsDashboardLayoutPayload
  rawPayload: PullsDashboardLayoutPayload
}

const PullsDashboardPayloadContext = createContext<PullsDashboardPayloadContextValue | null>(null)

// Dynamic context: changes on user interaction (search, filter, pagination)
interface PullsDashboardSearchContextValue {
  fetchedQuery: string
  currentPage: number
  locationSidebarLinkId?: string
  isLoading: boolean
  maxPrAge: PullsInboxMaxAgeType
  setMaxPrAge: (maxPrAge: PullsInboxMaxAgeType) => void
  fetchResults: (args: {q: string; page: number; sidebarLinkId?: string}) => void
  // Optimistic update for inbox section preferences
  setSectionPreferences: (prefs: {order: string[]; hidden: string[]}) => void
}

const PullsDashboardSearchContext = createContext<PullsDashboardSearchContextValue | null>(null)

export function PullsDashboardSurfaceStateProvider({
  children,
  payload,
  isLoading,
}: {
  children: ReactNode
  payload: PullsDashboardLayoutPayload
  isLoading: boolean
}) {
  const {pathname} = useLocation()
  const isOnInbox = isOnInboxPath({pathname})

  const {fetchedQuery, currentPage, fetchResults, locationSidebarLinkId} = useListResults({
    defaultFilterValue: isOnInbox ? '' : queryMap().authored,
  })

  const [maxPrAge, setMaxPrAge] = useState<PullsInboxMaxAgeType>(payload.filters?.maxPrAge ?? PullsInboxMaxAge.OneMonth)

  const [pendingPrefs, setPendingPrefs] = useState<{order: string[]; hidden: string[]} | null>(null)

  // Compute the effective optimistic prefs inline: once the payload reflects
  // what we saved, ignore `pendingPrefs` so future renders read straight from
  // the payload.
  const sectionPrefs = pendingPrefs && !payloadMatchesPrefs(payload, pendingPrefs) ? pendingPrefs : null

  const setSectionPreferences = useCallback(({order, hidden}: {order: string[]; hidden: string[]}) => {
    setPendingPrefs({order, hidden})
  }, [])

  const effectivePayload = useMemo<PullsDashboardLayoutPayload>(() => {
    if (!sectionPrefs) {
      return payload
    }
    // Hidden sections are removed from inboxSectionQueries server-side; mirror that
    // for the optimistic update so the render filter doesn't leave hidden sections
    // in the rendered list until the next layout refetch. Conversely, when a user
    // un-hides a section that the server had previously omitted, add it back so it
    // becomes renderable immediately (consumers fall back to the section id when
    // no query string is provided).
    let inboxSectionQueries = payload.inboxSectionQueries
    if (inboxSectionQueries) {
      const hiddenSet = new Set(sectionPrefs.hidden)
      const knownIds = new Set<string>([
        ...Object.keys(inboxSectionQueries),
        ...(payload.hiddenSections ?? []),
        ...(payload.sectionOrder ?? []),
        ...sectionPrefs.order,
      ])
      const next: Record<string, string> = {}
      for (const id of knownIds) {
        if (hiddenSet.has(id)) continue
        next[id] = inboxSectionQueries[id] ?? id
      }
      inboxSectionQueries = next
    }
    return {
      ...payload,
      inboxSectionQueries,
      sectionOrder: sectionPrefs.order,
      hiddenSections: sectionPrefs.hidden,
    }
  }, [payload, sectionPrefs])

  const payloadValue = useMemo<PullsDashboardPayloadContextValue>(
    () => ({payload: effectivePayload, rawPayload: payload}),
    [effectivePayload, payload],
  )

  const searchValue: PullsDashboardSearchContextValue = useMemo(
    () => ({
      fetchedQuery,
      currentPage,
      fetchResults,
      locationSidebarLinkId,
      isLoading,
      maxPrAge,
      setMaxPrAge,
      setSectionPreferences,
    }),
    [
      fetchedQuery,
      currentPage,
      fetchResults,
      locationSidebarLinkId,
      isLoading,
      maxPrAge,
      setMaxPrAge,
      setSectionPreferences,
    ],
  )

  return (
    <PullsDashboardPayloadContext value={payloadValue}>
      <PullsDashboardSearchContext value={searchValue}>{children}</PullsDashboardSearchContext>
    </PullsDashboardPayloadContext>
  )
}

export function arraysEqual(a: readonly string[], b: readonly string[]): boolean {
  return a.length === b.length && a.every((value, index) => value === b[index])
}

function payloadMatchesPrefs(
  payload: PullsDashboardLayoutPayload,
  prefs: {order: string[]; hidden: string[]},
): boolean {
  return arraysEqual(payload.sectionOrder ?? [], prefs.order) && arraysEqual(payload.hiddenSections ?? [], prefs.hidden)
}

export function usePullsDashboardPayload() {
  const context = use(PullsDashboardPayloadContext)
  if (!context) {
    throw new Error('usePullsDashboardPayload must be used within a PullsDashboardSurfaceStateProvider')
  }
  return context.payload
}

export function usePullsDashboardSearch() {
  const context = use(PullsDashboardSearchContext)
  if (!context) {
    throw new Error('usePullsDashboardSearch must be used within a PullsDashboardSurfaceStateProvider')
  }
  return context
}

export function usePullsDashboardSurfaceStateContext() {
  const payloadContext = use(PullsDashboardPayloadContext)
  const searchContext = use(PullsDashboardSearchContext)
  if (!payloadContext || !searchContext) {
    throw new Error('usePullsDashboardSurfaceStateContext must be used within a PullsDashboardSurfaceStateProvider')
  }
  return {...payloadContext, ...searchContext}
}

/**
 * Non-throwing variant of `usePullsDashboardSurfaceStateContext`. Returns `null`
 * when no provider is present so callers can degrade gracefully (e.g. when the
 * inbox component is rendered in a transient router state before the layout
 * payload has resolved, or in tests/stories that mount it standalone).
 */
export function useOptionalPullsDashboardSurfaceStateContext() {
  const payloadContext = use(PullsDashboardPayloadContext)
  const searchContext = use(PullsDashboardSearchContext)
  if (!payloadContext || !searchContext) return null
  return {...payloadContext, ...searchContext}
}
