/**
 * Returns the metadata-enriched list of inbox sections, preserving the canonical
 * order from `inboxSections`.
 */
export function getAvailableInboxSections(availableSectionIds: readonly string[]): DashboardSectionConfig[] {
  const availableSet = new Set(availableSectionIds)
  return inboxSections.filter(section => availableSet.has(section.id))
}

/**
 * Convenience hook used by the layout to compute the default order list from
 * the definition-derived available section ids.
 */
export function useDefaultInboxSectionOrder(availableSectionIds: readonly string[]) {
  return useMemo(() => getAvailableInboxSections(availableSectionIds).map(s => s.id), [availableSectionIds])
}
