import {useState} from 'react'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {ListView} from '@github-ui/list-view'
import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ChevronDownIcon, ChevronRightIcon} from '@primer/octicons-react'
import {CounterLabel, IconButton} from '@primer/react'

import styles from './PullsInboxSection.module.css'
import {PullsInboxListItem} from './PullsInboxListItem'
import {SectionQueryPopover} from './SectionQueryPopover'
import type {DashboardSectionConfig, EnrichedPull} from './types/list-types'
import {SharedDashboardBlankslate} from '../shared/SharedDashboardBlankslate'
import {PullsDashboardInboxSectionSkeleton} from './PullsInboxSectionSkeleton'

export interface PullsInboxSectionProps {
  config: DashboardSectionConfig
  enrichedPulls: EnrichedPull[]
  totalCount: number
  hasMore: boolean
  isPending: boolean
  isError: boolean
  isDeferredError: boolean
  loadMore: () => void
  trackHPC?: boolean
  isCollapsed: boolean
  onCollapsedChange: (collapsed: boolean) => void
  isAgentAttributionEnabled?: boolean
}

export function PullsInboxSection({
  config,
  enrichedPulls,
  totalCount,
  hasMore,
  isPending,
  isError,
  isDeferredError,
  loadMore,
  trackHPC,
  isCollapsed,
  onCollapsedChange,
  isAgentAttributionEnabled,
}: PullsInboxSectionProps) {
  const sectionResultLimit = 25
  const isEmpty = !isPending && totalCount === 0
  const sectionQueries = config.queries ?? []
  const showSectionQueryPopover =
    isFeatureEnabled('pull_request_inbox_section_query_popover') && sectionQueries.length > 0

  const [emptyExpanded, setEmptyExpanded] = useState(false)
  const effectiveCollapsed = isCollapsed || (isEmpty && !emptyExpanded)

  if (isPending && !effectiveCollapsed) {
    return <PullsDashboardInboxSectionSkeleton name={config.name} numItems={config.maxItems} />
  }

  if (isError) {
    return (
      <section aria-label={config.name}>
        <h2 className="h4 mb-2">{config.name}</h2>
        <div className={styles.listContainer}>
          <SharedDashboardBlankslate dashboardType="pull-requests" variant="error" />
        </div>
      </section>
    )
  }

  if (config.id === 'merge-queue' && totalCount === 0) return null

  const titleId = `pulls-inbox-section-${config.id}`
  const bodyId = `pulls-inbox-section-body-${config.id}`
  const hasReachedResultLimit =
    !hasMore && enrichedPulls.length >= sectionResultLimit && totalCount >= sectionResultLimit

  return (
    <section
      aria-label={config.name}
      data-testid={`pulls-inbox-section-${config.id}`}
      {...(trackHPC ? {'data-hpc': true} : {})}
    >
      <div className={styles.sectionHeader}>
        <IconButton
          className={styles.collapseButton}
          icon={effectiveCollapsed ? ChevronRightIcon : ChevronDownIcon}
          aria-label={`${effectiveCollapsed ? 'Expand' : 'Collapse'} ${config.name}`}
          aria-expanded={!effectiveCollapsed}
          aria-controls={bodyId}
          onClick={() => {
            const willExpand = effectiveCollapsed
            if (isEmpty) setEmptyExpanded(willExpand)
            onCollapsedChange(!effectiveCollapsed)
          }}
          variant="invisible"
          size="small"
        />
        <h2 id={titleId} className="h4">
          {config.name}
        </h2>

        <CounterLabel>{totalCount}</CounterLabel>
        {showSectionQueryPopover && (
          <SectionQueryPopover sectionName={config.name} description={config.description} queries={sectionQueries} />
        )}
      </div>
      {!effectiveCollapsed && (
        <div id={bodyId}>
          {isDeferredError && (
            <p className="f6 color-fg-muted mt-2 mb-0" role="status">
              Some status details could not be loaded.
            </p>
          )}
          <div className={styles.listContainer}>
            {enrichedPulls.length > 0 ? (
              <ListView
                className="border border-color-muted rounded-2 overflow-hidden"
                title={config.name}
                titleHeaderTag="h2"
                ariaLabelledBy={titleId}
              >
                {enrichedPulls.map(pull => (
                  <PullsInboxListItem key={pull.id} row={pull} isAgentAttributionEnabled={isAgentAttributionEnabled} />
                ))}
                {hasMore && (
                  <ListItem
                    className={styles.loadMoreRow}
                    title={
                      <ListItemTitle
                        value="Load more"
                        className="pt-0"
                        onClick={loadMore}
                        linkProps={{as: 'button', type: 'button', className: styles.loadMoreButton}}
                      />
                    }
                  />
                )}
              </ListView>
            ) : (
              <SharedDashboardBlankslate
                dashboardType="pull-requests"
                variant="emptyInbox"
                descriptionOverride={config.emptyDescription}
              />
            )}
          </div>
          {hasReachedResultLimit && <p className="f6 color-fg-muted mt-2 mb-0">Results are limited to 25.</p>}
        </div>
      )}
    </section>
  )
}
