import {useMemo} from 'react'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {Compile} from '@github-ui/react-query-persister/typebox/compile'
import {createPersister} from '@github-ui/react-query-persister'
import {ErrorBoundary} from '@github-ui/react-core/error-boundary'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {PullsInboxSection} from '@github-ui/shared-dashboard-lists/pulls/PullsInboxSection'
import type {DashboardSectionConfig} from '@github-ui/shared-dashboard-lists/pulls/types/list-types'
import {SharedDashboardBlankslate} from '@github-ui/shared-dashboard-lists/shared/SharedDashboardBlankslate'
import {useAnalytics} from '@github-ui/use-analytics'
import {getAvailableInboxSections} from '../constants/inbox-sections'
import {
  arraysEqual,
  useOptionalPullsDashboardSurfaceStateContext,
  usePullsDashboardPayload,
  usePullsDashboardSearch,
} from '../contexts/PullsDashboardSurfaceStateContext'
import {DEFAULT_FIRST_INBOX_SECTION, normalizeInboxSectionPreferences} from '../helpers/inbox-section-preferences'
import {useSaveCollapsedSection} from '../hooks/use-save-collapsed-section'
import {useSectionData} from '../hooks/use-section-data'
import {SectionDataResultSchema} from '../types/routes-types'
import {
  getActiveInboxQueryName,
  getAvailableInboxSectionIds,
  isInboxSectionId,
  pullsDashboardInboxRoute,
} from './pulls-dashboard-inbox-route'

export function PullsDashboardInboxComponent() {
  // TODO(pull_request_inbox_customize_sections cleanup): when this flag is
  // fully rolled out, drop `customizeSectionsEnabled` (and its plumbing into
  // `getActiveInboxQueryName`)
  const customizeSectionsEnabled = isFeatureEnabled('pull_request_inbox_customize_sections')

  const layoutContext = useOptionalPullsDashboardSurfaceStateContext()
  const rawSectionOrder = layoutContext?.payload.sectionOrder
  const rawHiddenSections = layoutContext?.payload.hiddenSections
  const inboxSectionQueriesFromPayload = layoutContext?.payload.inboxSectionQueries

  // Fall back to the optimistic payload when no separate rawPayload is
  // provided.
  const hasOptimisticSectionPreferences =
    layoutContext?.rawPayload &&
    (!arraysEqual(layoutContext.payload.sectionOrder ?? [], layoutContext.rawPayload.sectionOrder ?? []) ||
      !arraysEqual(layoutContext.payload.hiddenSections ?? [], layoutContext.rawPayload.hiddenSections ?? []))
  const firstVisiblePayload = hasOptimisticSectionPreferences
    ? layoutContext.payload
    : (layoutContext?.rawPayload ?? layoutContext?.payload)

  const firstVisibleSectionOrder = firstVisiblePayload?.sectionOrder
  const firstVisibleHiddenSections = firstVisiblePayload?.hiddenSections
  const sectionOrder = useMemo(() => rawSectionOrder ?? [], [rawSectionOrder])
  const hiddenSections = useMemo(() => rawHiddenSections ?? [], [rawHiddenSections])
  const firstVisibleOrder = useMemo(() => firstVisibleSectionOrder ?? [], [firstVisibleSectionOrder])
  const firstVisibleHidden = useMemo(() => firstVisibleHiddenSections ?? [], [firstVisibleHiddenSections])
  const availableSectionIds = useMemo(() => getAvailableInboxSectionIds(), [])

  // `inboxSectionQueries` is the source of truth for sections that can render
  // right now. The backend removes hidden sections from this map.
  const renderableSectionIds = useMemo(() => {
    if (inboxSectionQueriesFromPayload === undefined) return availableSectionIds
    return Object.keys(inboxSectionQueriesFromPayload)
  }, [availableSectionIds, inboxSectionQueriesFromPayload])

  const availableSections = useMemo(() => getAvailableInboxSections(renderableSectionIds), [renderableSectionIds])
  const renderableAvailableSectionIds = useMemo(() => availableSections.map(section => section.id), [availableSections])
  const normalizedVisiblePreferences = useMemo(
    () =>
      normalizeInboxSectionPreferences({
        order: sectionOrder,
        hidden: hiddenSections,
        availableIds: renderableAvailableSectionIds,
      }),
    [hiddenSections, renderableAvailableSectionIds, sectionOrder],
  )

  const visibleSections = useMemo(() => {
    const hidden = new Set(normalizedVisiblePreferences.hiddenSections)
    // Filter out any ids unknown to the query registry as a runtime guard
    // against drift between `inboxSections` and `INBOX_SECTION_DEFINITIONS`.
    const userVisible = availableSections.filter(section => !hidden.has(section.id) && isInboxSectionId(section.id))

    // Sort by sectionOrder index. Sections missing from sectionOrder (e.g. new
    // sections launched after a user customized) keep their relative order at the
    // end via a stable sort with Infinity-fallback indexes.
    const orderIndex = new Map(normalizedVisiblePreferences.sectionOrder.map((id, idx) => [id, idx]))
    return [...userVisible].sort((a, b) => {
      const ai = orderIndex.get(a.id) ?? Number.POSITIVE_INFINITY
      const bi = orderIndex.get(b.id) ?? Number.POSITIVE_INFINITY
      return ai - bi
    })
  }, [availableSections, normalizedVisiblePreferences])

  // Derive the first-visible section id from the server payload, except while
  // optimistic section preferences are active. During that window, the rendered
  // section list and query-name selection must agree on order and hidden state.
  // Only used when the customize-sections flag is on.
  // Pass the available section ids so a saved order
  // beginning with a currently disabled section doesn't cause the actual top
  // section to be deferred. This intentionally does not use
  // `inboxSectionQueries`, because hidden sections are removed from that map.
  const normalizedFirstVisiblePreferences = useMemo(
    () =>
      normalizeInboxSectionPreferences({
        order: firstVisibleOrder,
        hidden: firstVisibleHidden,
        availableIds: availableSectionIds,
      }),
    [availableSectionIds, firstVisibleHidden, firstVisibleOrder],
  )
  const firstVisibleSectionId = useMemo(
    () =>
      customizeSectionsEnabled ? normalizedFirstVisiblePreferences.firstVisibleSectionId : DEFAULT_FIRST_INBOX_SECTION,
    [customizeSectionsEnabled, normalizedFirstVisiblePreferences.firstVisibleSectionId],
  )

  return (
    <div data-testid="pulls-dashboard-inbox" className="tmp-pt-3">
      <div className="d-flex flex-column gap-4">
        {visibleSections.map(section => (
          <ErrorBoundary
            key={section.id}
            boundaryName={`InboxDashboardSection-${section.id}`}
            fallback={
              <section aria-label={section.name}>
                <h2 className="h4 mb-2">{section.name}</h2>
                <SharedDashboardBlankslate dashboardType="pull-requests" variant="error" />
              </section>
            }
          >
            <InboxDashboardSection
              section={section}
              firstVisibleSectionId={firstVisibleSectionId}
              customizeSectionsEnabled={customizeSectionsEnabled}
            />
          </ErrorBoundary>
        ))}
      </div>
    </div>
  )
}

const sectionDataResultValidator = Compile(SectionDataResultSchema)

function InboxDashboardSection({
  section,
  firstVisibleSectionId,
  customizeSectionsEnabled,
}: {
  section: DashboardSectionConfig
  firstVisibleSectionId: string
  customizeSectionsEnabled: boolean
}) {
  const queryName = getActiveInboxQueryName(section.id, firstVisibleSectionId, customizeSectionsEnabled)
  if (!queryName) return null
  return <InboxDashboardSectionContent section={section} queryName={queryName} />
}

function InboxDashboardSectionContent({
  section,
  queryName,
}: {
  section: DashboardSectionConfig
  queryName: NonNullable<ReturnType<typeof getActiveInboxQueryName>>
}) {
  const {sendAnalyticsEvent} = useAnalytics()
  const persistenceEnabled = isFeatureEnabled('pulls_api_persistence')

  const persister = useMemo(
    () =>
      createPersister({
        validator: sectionDataResultValidator,
        sendAnalyticsEvent,
        prefix: 'pulls-dashboard-inbox',
        enabled: persistenceEnabled,
      }),
    [persistenceEnabled, sendAnalyticsEvent],
  )

  const {data, isPending, isError} = useRouteQuery(pullsDashboardInboxRoute, queryName, {persister})

  const {inboxSectionQueries: inboxSectionQueriesFromLayout, collapsedSections: collapsedSectionsFromLayout} =
    usePullsDashboardPayload()
  const {fetchedQuery, maxPrAge} = usePullsDashboardSearch()

  const isInitiallyCollapsed = collapsedSectionsFromLayout?.includes(section.id) ?? false
  const {isCollapsed, setCollapsed} = useSaveCollapsedSection(section.id, isInitiallyCollapsed)

  const queryId = inboxSectionQueriesFromLayout?.[section.id] ?? section.id

  // Visible count is reset on changes to query or max PR age
  const scopeKey = [queryId, maxPrAge, fetchedQuery].join(' ')

  const sectionData = useSectionData({
    sectionId: section.id,
    scopeKey,
    primaryData: data,
    initialVisibleCount: section.maxItems,
    isCollapsed,
  })

  return (
    <PullsInboxSection
      config={section}
      {...sectionData}
      isPending={isPending}
      isError={isError}
      totalCount={data?.totalCount ?? 0}
      trackHPC={section.id === 'review-requested'}
      isCollapsed={isCollapsed}
      onCollapsedChange={setCollapsed}
      isAgentAttributionEnabled={isFeatureEnabled('agent_author_search_expansion_ui_pulls')}
    />
  )
}
