import {queryFnFetch} from '@github-ui/react-core/future/query-fn-fetch'
import {QueryRouteQueryType} from '@github-ui/react-core/future/data-router-types'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {IS_SERVER} from '@github-ui/ssr-utils'

import {dashboardSurfaceAppBuilder} from '../config/app-builder'
import {PULLS_INBOX_PATH} from '../constants/routes'
import {isBlockingInboxSection, isDeferredInboxSection} from '../helpers/inbox-section-preferences'
import type {PullsDashboardSurfacePayload, SectionDataResult} from '../types/routes-types'

const PULLS_DASHBOARD_INBOX_ROUTE_ID = 'pullsDashboardInboxRoute'

type EmbeddedPayload = Record<string, unknown>

interface InboxSectionQueryResponse {
  payload?: {
    pullsInboxSurfaceContentRoute?: PullsDashboardSurfacePayload
  }
}

function extractSectionData(json: InboxSectionQueryResponse): SectionDataResult {
  const payload = json.payload?.pullsInboxSurfaceContentRoute
  if (!payload) {
    throw new Error('Unexpected response shape: missing pullsInboxSurfaceContentRoute')
  }
  return {results: payload.results, totalCount: payload.pageInfo.totalCount}
}

function sectionQueryDeps(sectionId: string) {
  return ({searchParams}: {searchParams: URLSearchParams}) => {
    return {
      pathname: `${PULLS_INBOX_PATH}/queries`,
      searchParams: {
        filter: `${sectionId} ${searchParams.get('filter') || ''}`.trim(),
        max_pr_age: searchParams.get('max_pr_age') || '1m',
      },
    }
  }
}

async function sectionQueryFn(queryKey: Parameters<typeof queryFnFetch>[0]): Promise<SectionDataResult> {
  const json = await queryFnFetch<InboxSectionQueryResponse>(queryKey)
  return extractSectionData(json)
}

/** Combine an optional feature-flag gate with another predicate */
function combineEnabled(featureFlag: (() => boolean) | undefined, gate: () => boolean) {
  if (!featureFlag) return gate
  return () => featureFlag() && gate()
}

function hasEmbeddedDataForQuery(queryName: string): boolean | undefined {
  if (!IS_SERVER) return undefined

  try {
    const embeddedPayload = dashboardSurfaceAppBuilder.getEmbeddedData()?.payload as EmbeddedPayload | undefined
    if (!embeddedPayload) return undefined

    const routePayload = embeddedPayload[PULLS_DASHBOARD_INBOX_ROUTE_ID] as EmbeddedPayload | undefined
    return embeddedPayload[queryName] !== undefined || routePayload?.[queryName] !== undefined
  } catch {
    return undefined
  }
}

function sectionQueryEnabled(queryName: string, featureFlag: (() => boolean) | undefined, gate: () => boolean) {
  return combineEnabled(featureFlag, () => hasEmbeddedDataForQuery(queryName) ?? gate())
}

const customizeSectionsFlag = () => isFeatureEnabled('pull_request_inbox_customize_sections')
const customizeSectionsDisabled = () => !customizeSectionsFlag()

/**
 * Build a Blocking + Deferred query pair for one section, ONLY active when the
 * `pull_request_inbox_customize_sections` feature flag is enabled. Both
 * variants share the same `queryFn`/`queryDeps`; gating is done via `enabled`
 * so that the cookie-derived first-visible section runs as Blocking and the
 * rest run as Deferred.
 */
function sectionQueryPair<Id extends string, Base extends string>(id: Id, baseName: Base, flag?: () => boolean) {
  const flagAndCustomize = combineEnabled(flag, customizeSectionsFlag)
  const blockingQueryName = `${baseName}Blocking` as const
  const deferredQueryName = `${baseName}Deferred` as const
  return [
    {
      queryName: blockingQueryName,
      queryDeps: sectionQueryDeps(id),
      queryFn: sectionQueryFn,
      type: QueryRouteQueryType.Blocking,
      enabled: sectionQueryEnabled(
        blockingQueryName,
        flagAndCustomize,
        isBlockingInboxSection(id, getAvailableInboxSectionIds),
      ),
    },
    {
      queryName: deferredQueryName,
      queryDeps: sectionQueryDeps(id),
      queryFn: sectionQueryFn,
      type: QueryRouteQueryType.Deferred,
      enabled: sectionQueryEnabled(
        deferredQueryName,
        flagAndCustomize,
        isDeferredInboxSection(id, getAvailableInboxSectionIds),
      ),
    },
  ] as const
}

/**
 * Legacy single-query registration, used only when the customize-sections
 * feature flag is OFF.
 *
 * TODO(pull_request_inbox_customize_sections cleanup): delete this helper,
 * the `legacySectionQuery(...)` entries below, the `legacy` field on
 * `INBOX_SECTION_QUERY_NAME_PAIRS`, and the `customizeSectionsDisabled` /
 * `customizeSectionsEnabled` branches once the flag is fully rolled out and
 * the backend stops emitting unsuffixed `section<Id>` SSR payloads.
 */
function legacySectionQuery<Id extends string, Name extends string>(
  id: Id,
  queryName: Name,
  type: QueryRouteQueryType,
  flag?: () => boolean,
) {
  return {
    queryName,
    queryDeps: sectionQueryDeps(id),
    queryFn: sectionQueryFn,
    type,
    enabled: combineEnabled(flag, customizeSectionsDisabled),
  } as const
}

const teamReviewRequestedFlag = () => isFeatureEnabled('team_review_requested_by_user_filter')

/**
 * Configuration for inbox sections: their id, the camelCase base used
 * for queryName generation (`section<Base>` + Blocking/Deferred/legacy
 * suffix), the legacy QueryRouteQueryType used when the customize-sections
 * flag is OFF, and an optional feature flag gating the section.
 *
 * Adding a new section requires adding an entry here and a matching entry
 * in `inboxSections` (`constants/inbox-sections.ts`).
 */
const INBOX_SECTION_DEFINITIONS = [
  {id: 'review-requested', base: 'sectionReviewRequested', legacyType: QueryRouteQueryType.Blocking},
  {
    id: 'team-review-requested',
    base: 'sectionTeamReviewRequested',
    legacyType: QueryRouteQueryType.Deferred,
    flag: teamReviewRequestedFlag,
  },
  {id: 'your-drafts', base: 'sectionYourDrafts', legacyType: QueryRouteQueryType.Deferred},
  {
    id: 'waiting-for-review',
    base: 'sectionWaitingForReview',
    legacyType: QueryRouteQueryType.Deferred,
  },
  {id: 'needs-action', base: 'sectionNeedsAction', legacyType: QueryRouteQueryType.Deferred},
  {id: 'ready-to-merge', base: 'sectionReadyToMerge', legacyType: QueryRouteQueryType.Deferred},
  {id: 'merge-queue', base: 'sectionMergeQueue', legacyType: QueryRouteQueryType.Deferred},
] as const satisfies ReadonlyArray<{
  id: string
  base: string
  legacyType: QueryRouteQueryType
  flag?: () => boolean
}>

type InboxSectionDefinition = (typeof INBOX_SECTION_DEFINITIONS)[number]

export function getAvailableInboxSectionIds() {
  return INBOX_SECTION_DEFINITIONS.filter(section => !('flag' in section) || section.flag()).map(section => section.id)
}

export function isInboxSectionId(id: string): id is InboxSectionId {
  return id in INBOX_SECTION_QUERY_NAME_PAIRS
}

/**
 * Per-section Blocking + Deferred query name pairs and the legacy single
 * query name, derived from `INBOX_SECTION_DEFINITIONS`. Both schemes are
 * registered on every request; exactly one is active depending on the
 * `pull_request_inbox_customize_sections` flag.
 */
const INBOX_SECTION_QUERY_NAME_PAIRS = Object.fromEntries(
  INBOX_SECTION_DEFINITIONS.map(s => [
    s.id,
    {blocking: `${s.base}Blocking`, deferred: `${s.base}Deferred`, legacy: s.base},
  ]),
) as {
  [Def in InboxSectionDefinition as Def['id']]: {
    blocking: `${Def['base']}Blocking`
    deferred: `${Def['base']}Deferred`
    legacy: Def['base']
  }
}

type InboxSectionId = keyof typeof INBOX_SECTION_QUERY_NAME_PAIRS

export type InboxSectionQueryName =
  | (typeof INBOX_SECTION_QUERY_NAME_PAIRS)[InboxSectionId]['blocking']
  | (typeof INBOX_SECTION_QUERY_NAME_PAIRS)[InboxSectionId]['deferred']
  | (typeof INBOX_SECTION_QUERY_NAME_PAIRS)[InboxSectionId]['legacy']

/**
 * Returns the queryName a consumer should read for a given section. When the
 * customize-sections feature flag is OFF, returns the legacy unsuffixed name
 * (matching the pre-customize backend payloads). When ON, returns the
 * Blocking variant for the first visible section and Deferred for the rest.
 *
 * TODO(pull_request_inbox_customize_sections cleanup): drop the
 * `customizeSectionsEnabled` parameter and the legacy branch once the flag
 * is fully rolled out; callers can then always select Blocking/Deferred.
 */
export function getActiveInboxQueryName(
  sectionId: string,
  firstVisibleSectionId: string | undefined,
  customizeSectionsEnabled: boolean,
): InboxSectionQueryName | null {
  if (!isInboxSectionId(sectionId)) return null
  const pair = INBOX_SECTION_QUERY_NAME_PAIRS[sectionId]
  if (!customizeSectionsEnabled) return pair.legacy
  return firstVisibleSectionId === sectionId ? pair.blocking : pair.deferred
}

export const pullsDashboardInboxRoute = dashboardSurfaceAppBuilder.createQueryRouteConfig(
  PULLS_DASHBOARD_INBOX_ROUTE_ID,
  {
    path: PULLS_INBOX_PATH,
    queries: [
      // New customize-sections flow: Blocking + Deferred per section, gated by
      // the `pull_request_inbox_customize_sections` flag.
      ...sectionQueryPair('review-requested', 'sectionReviewRequested'),
      ...sectionQueryPair('team-review-requested', 'sectionTeamReviewRequested', teamReviewRequestedFlag),
      ...sectionQueryPair('your-drafts', 'sectionYourDrafts'),
      ...sectionQueryPair('waiting-for-review', 'sectionWaitingForReview'),
      ...sectionQueryPair('needs-action', 'sectionNeedsAction'),
      ...sectionQueryPair('ready-to-merge', 'sectionReadyToMerge'),
      ...sectionQueryPair('merge-queue', 'sectionMergeQueue'),
      // Legacy single-query registrations, active only when the
      // customize-sections flag is OFF. Preserves pre-PR SSR payload keys.
      // TODO(pull_request_inbox_customize_sections cleanup): remove these
      // entries once the flag is fully rolled out.
      legacySectionQuery('review-requested', 'sectionReviewRequested', QueryRouteQueryType.Blocking),
      legacySectionQuery(
        'team-review-requested',
        'sectionTeamReviewRequested',
        QueryRouteQueryType.Deferred,
        teamReviewRequestedFlag,
      ),
      legacySectionQuery('your-drafts', 'sectionYourDrafts', QueryRouteQueryType.Deferred),
      legacySectionQuery('waiting-for-review', 'sectionWaitingForReview', QueryRouteQueryType.Deferred),
      legacySectionQuery('needs-action', 'sectionNeedsAction', QueryRouteQueryType.Deferred),
      legacySectionQuery('ready-to-merge', 'sectionReadyToMerge', QueryRouteQueryType.Deferred),
      legacySectionQuery('merge-queue', 'sectionMergeQueue', QueryRouteQueryType.Deferred),
    ],
  },
)
