// eslint-disable-next-line no-restricted-imports
import {reportError} from '@github-ui/failbot'
import {isRouteErrorResponse, useRouteError} from '@github-ui/react-router'
import {isResponseError} from '@github-ui/react-core/future/response-error'
import {Blankslate} from '@primer/react/experimental'
import {useEffect, useRef} from 'react'

// Mirrors handleIfNotReported from @github-ui/react-core/future/RouterErrorBoundary
const reportedErrors = new WeakSet<object>()
function reportIfNotReported<T extends object>(error: T, report: (err: T) => void) {
  if (!reportedErrors.has(error)) {
    reportedErrors.add(error)
    report(error)
  }
}

export function DashboardRouteErrorBoundary() {
  const routeError = useRouteError()
  const appNameRef = useRef('dashboard-surface')

  useEffect(() => {
    if (routeError && typeof routeError === 'object') {
      reportIfNotReported(routeError, error => {
        reportError(error, {critical: true, reactAppName: appNameRef.current})
        if (process.env.NODE_ENV === 'development') {
          // eslint-disable-next-line no-console
          console.error('Error in DashboardRouteErrorBoundary', error)
        }
      })
    }
  }, [routeError])

  // 404 during unmount is a benign Turbo navigation race — render nothing
  if (isRouteErrorResponse(routeError) && routeError.status === 404) {
    return null
  }

  if (isResponseError(routeError)) {
    return (
      <Blankslate border={false} spacious={false}>
        <Blankslate.Heading>Unable to load pull requests.</Blankslate.Heading>
        <Blankslate.Description>
          The server returned an error. Please reload the page and try again.
        </Blankslate.Description>
      </Blankslate>
    )
  }

  return (
    <Blankslate border={false} spacious={false}>
      <Blankslate.Heading>Something went wrong.</Blankslate.Heading>
      <Blankslate.Description>
        An unexpected error occurred. Please reload the page and try again.
      </Blankslate.Description>
    </Blankslate>
  )
}
