import {deleteCookie, getCookie, setCookie} from '@github-ui/cookies'
import {useRef, useState, useSyncExternalStore} from 'react'

export const COOKIE_NAME = 'dashboard_surface_inbox_options_tip_dismissed'
export const LEGACY_COOKIE_NAME = 'dashboard_surface_default_view_tip_dismissed'
const COOKIE_EXPIRY_MS = 100 * 24 * 60 * 60 * 1000 // 100 days

const noop = () => () => {}

/**
 * Hook to manage and persist the dismissed state of the inbox-options tip via a browser cookie.
 * Returns the current dismissed state and a function to dismiss the tip.
 *
 * Uses useSyncExternalStore so the popover is suppressed during SSR (server snapshot
 * returns true) and only shown on the client when the cookie is confirmed absent.
 */
export function useInboxOptionsTipDismissed() {
  const cookieValue = useSyncExternalStore(
    noop,
    () => getCookie(COOKIE_NAME)?.value === '1',
    () => true,
  )

  const [manuallyDismissed, setManuallyDismissed] = useState(false)
  const savedStateRef = useRef(false)

  const isDismissed = cookieValue || manuallyDismissed

  function dismiss() {
    if (savedStateRef.current) {
      return
    }

    savedStateRef.current = true

    const expireTime = new Date(Date.now() + COOKIE_EXPIRY_MS).toUTCString()
    setCookie(COOKIE_NAME, '1', expireTime)
    deleteCookie(LEGACY_COOKIE_NAME)
    setManuallyDismissed(true)
  }

  return {isDismissed, dismiss}
}
