import {announce} from '@github-ui/aria-live'
import {DragAndDrop, type OnDropArgs} from '@github-ui/drag-and-drop'
import type {DashboardSectionConfig} from '@github-ui/shared-dashboard-lists/pulls/types/list-types'
import {ArrowDownIcon, ArrowUpIcon, EyeClosedIcon, KebabHorizontalIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Button, Dialog, IconButton} from '@primer/react'
import {memo, useCallback, useMemo, useRef, useState} from 'react'

import {useUpdateSectionPreferences} from '../../hooks/use-update-section-preferences'
import styles from './CustomizeSectionsDialog.module.css'

interface CustomizeSectionsDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  /** Currently rendered section ids and order, drawn from the layout payload. */
  initialOrder: string[]
  /** Currently hidden section ids, drawn from the layout payload. */
  initialHidden: string[]
  /** Section ids enabled for the current viewer (after feature-flag filtering). */
  availableSections: DashboardSectionConfig[]
  /** Default order to restore when the user clicks "Reset to default". */
  defaultOrder: string[]
  /** Called with the saved preferences after they are written to client cookies, so the surface state context can apply them optimistically. */
  onSaved: (prefs: {order: string[]; hidden: string[]}) => void
}

export function CustomizeSectionsDialog({open, ...props}: CustomizeSectionsDialogProps) {
  // Gate on `open` at the outer boundary so the inner component (and its
  // unsaved-edit `useState`) is fully unmounted on close. Reopening then
  // re-derives state from the current `initialOrder`/`initialHidden` props
  // instead of resurrecting whatever the user was editing before Cancel.
  if (!open) return null
  return <CustomizeSectionsDialogContent {...props} />
}

type CustomizeSectionsDialogContentProps = Omit<CustomizeSectionsDialogProps, 'open'>

function CustomizeSectionsDialogContent({
  onOpenChange,
  initialOrder,
  initialHidden,
  availableSections,
  defaultOrder,
  onSaved,
}: CustomizeSectionsDialogContentProps) {
  const sectionsById = useMemo(() => {
    const map = new Map<string, DashboardSectionConfig>()
    for (const section of availableSections) map.set(section.id, section)
    return map
  }, [availableSections])

  const [localDialogState, setLocalDialogState] = useState<DialogState>(() =>
    buildInitialState(initialOrder, initialHidden, availableSections),
  )
  const {order, hiddenSet} = localDialogState
  const {visible, hidden} = useMemo(() => {
    const v: string[] = []
    const h: string[] = []
    for (const id of order) (hiddenSet.has(id) ? h : v).push(id)
    return {visible: v, hidden: h}
  }, [order, hiddenSet])
  const [isResetToDefault, setIsResetToDefault] = useState(false)

  const {saveSectionPreferences} = useUpdateSectionPreferences()

  const labelFor = useCallback((id: string) => sectionsById.get(id)?.name ?? id, [sectionsById])

  const visibleItems = useMemo(() => visible.map(id => ({id, title: labelFor(id)})), [visible, labelFor])

  // All edit callbacks use functional `setLocalDialogState(prev => ...)` so they don't
  // close over `local` — that keeps their identities stable across edits and
  // prevents `DragAndDrop` children from re-rendering on every state update.
  const moveVisible = useCallback(
    (id: string, direction: -1 | 1) => {
      setLocalDialogState(prev => computeMoveVisible(prev, id, direction) ?? prev)
      setIsResetToDefault(false)
      announce(`Moved ${labelFor(id)} ${direction === -1 ? 'up' : 'down'}`)
    },
    [labelFor],
  )

  const hideSection = useCallback(
    (id: string) => {
      setLocalDialogState(prev => computeHideSection(prev, id) ?? prev)
      setIsResetToDefault(false)
      announce(`Hid ${labelFor(id)}`)
    },
    [labelFor],
  )

  const showSection = useCallback(
    (id: string) => {
      setLocalDialogState(prev => computeShowSection(prev, id) ?? prev)
      setIsResetToDefault(false)
      announce(`Restored ${labelFor(id)}`)
    },
    [labelFor],
  )

  const onDrop = useCallback(
    ({dragMetadata, dropMetadata, isBefore}: OnDropArgs<string>) => {
      if (!dropMetadata || dragMetadata.id === dropMetadata.id) return
      setLocalDialogState(prev => computeReorder(prev, dragMetadata.id, dropMetadata.id, isBefore) ?? prev)
      setIsResetToDefault(false)
      announce(`Moved ${labelFor(dragMetadata.id)}`)
    },
    [labelFor],
  )

  const reset = useCallback(() => {
    const validDefault = defaultOrder.filter(id => sectionsById.has(id))
    setLocalDialogState({order: validDefault, hiddenSet: new Set()})
    setIsResetToDefault(true)
    announce('Reset to default order')
  }, [defaultOrder, sectionsById])

  const handleClose = useCallback(() => {
    onOpenChange(false)
  }, [onOpenChange])

  const handleSave = useCallback(() => {
    if (visible.length === 0) return
    const prefs = isResetToDefault ? {order: [], hidden: []} : {order, hidden: [...hiddenSet]}
    saveSectionPreferences(prefs)
    onSaved(prefs)
    handleClose()
  }, [visible.length, order, hiddenSet, isResetToDefault, saveSectionPreferences, onSaved, handleClose])

  const isLastVisible = visible.length <= 1

  return (
    <Dialog
      title="Customize sections"
      onClose={handleClose}
      width="xlarge"
      renderFooter={() => (
        <Dialog.Footer className={styles.footer}>
          <Button variant="danger" onClick={reset}>
            Reset to default
          </Button>
          <div className={styles.footerSpacer} />
          <Button onClick={handleClose}>Cancel</Button>
          <Button variant="primary" onClick={handleSave}>
            Save
          </Button>
        </Dialog.Footer>
      )}
    >
      <section aria-labelledby="customize-sections-visible-heading">
        <h3 id="customize-sections-visible-heading" className={styles.regionHeading}>
          Visible
        </h3>
        <DragAndDrop
          items={visibleItems}
          onDrop={onDrop}
          className={styles.list}
          role="list"
          renderOverlay={(item, index) => (
            <DragAndDrop.Item
              aria-label={item.title}
              index={index}
              id={item.id}
              title={item.title}
              key={item.id}
              hideTrigger
              isDragOverlay
            >
              <DragOverlayRow section={sectionsById.get(item.id)} />
            </DragAndDrop.Item>
          )}
        >
          {visible.map((id, index) => (
            <DragAndDrop.Item aria-label={labelFor(id)} index={index} id={id} title={labelFor(id)} key={id} hideTrigger>
              <VisibleSectionRow
                section={sectionsById.get(id)}
                index={index}
                count={visible.length}
                isLastVisible={isLastVisible}
                onMove={moveVisible}
                onHide={hideSection}
              />
            </DragAndDrop.Item>
          ))}
        </DragAndDrop>
      </section>

      {hidden.length > 0 && (
        <section aria-labelledby="customize-sections-hidden-heading" className={styles.hiddenRegion}>
          <h3 id="customize-sections-hidden-heading" className={styles.regionHeading}>
            Hidden
          </h3>
          {/* eslint-disable-next-line jsx-a11y/no-redundant-roles */}
          <ul className={styles.list} role="list">
            {hidden.map(id => (
              <HiddenSectionRow key={id} id={id} section={sectionsById.get(id)} onShow={showSection} />
            ))}
          </ul>
        </section>
      )}
    </Dialog>
  )
}

interface VisibleSectionRowProps {
  section: DashboardSectionConfig | undefined
  index: number
  count: number
  isLastVisible: boolean
  onMove: (id: string, direction: -1 | 1) => void
  onHide: (id: string) => void
}

// eslint-disable-next-line @typescript-eslint/no-shadow -- named function expression intentionally shares the outer name
const VisibleSectionRow = memo(function VisibleSectionRow({
  section,
  index,
  count,
  isLastVisible,
  onMove,
  onHide,
}: VisibleSectionRowProps) {
  const menuButtonRef = useRef<HTMLButtonElement>(null)
  if (!section) return null
  const hideAction = (
    <ActionList.Item onSelect={isLastVisible ? undefined : () => onHide(section.id)} disabled={isLastVisible}>
      <ActionList.LeadingVisual>
        <EyeClosedIcon />
      </ActionList.LeadingVisual>
      Hide section
      {isLastVisible && (
        <ActionList.Description variant="block">At least one section must remain visible</ActionList.Description>
      )}
    </ActionList.Item>
  )
  return (
    <div className={styles.row}>
      <DragAndDrop.DragTrigger />
      <div className={styles.rowText}>
        <span className={styles.rowLabel}>{section.name}</span>
        {section.description && <span className={styles.rowDescription}>{section.description}</span>}
      </div>
      <ActionMenu anchorRef={menuButtonRef}>
        <ActionMenu.Anchor>
          <IconButton
            ref={menuButtonRef}
            icon={KebabHorizontalIcon}
            variant="invisible"
            size="small"
            aria-label={`More options for ${section.name}`}
          />
        </ActionMenu.Anchor>
        <ActionMenu.Overlay>
          <ActionList>
            <ActionList.Item onSelect={() => onMove(section.id, -1)} disabled={index === 0}>
              <ActionList.LeadingVisual>
                <ArrowUpIcon />
              </ActionList.LeadingVisual>
              Move up
            </ActionList.Item>
            <ActionList.Item onSelect={() => onMove(section.id, 1)} disabled={index === count - 1}>
              <ActionList.LeadingVisual>
                <ArrowDownIcon />
              </ActionList.LeadingVisual>
              Move down
            </ActionList.Item>
            {hideAction}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    </div>
  )
})

interface HiddenSectionRowProps {
  id: string
  section: DashboardSectionConfig | undefined
  onShow: (id: string) => void
}

// eslint-disable-next-line @typescript-eslint/no-shadow -- named function expression intentionally shares the outer name
const HiddenSectionRow = memo(function HiddenSectionRow({id, section, onShow}: HiddenSectionRowProps) {
  const label = section?.name ?? id
  return (
    <li className={styles.row}>
      <span className={styles.hiddenIcon} aria-hidden="true">
        <EyeClosedIcon />
      </span>
      <div className={styles.rowText}>
        <span className={styles.rowLabel}>{label}</span>
        {section?.description && <span className={styles.rowDescription}>{section.description}</span>}
      </div>
      <Button variant="invisible" size="small" onClick={() => onShow(id)} aria-label={`Show ${label}`}>
        Show
      </Button>
    </li>
  )
})

// Stripped-down row used by the drag overlay.
// eslint-disable-next-line @typescript-eslint/no-shadow -- named function expression intentionally shares the outer name
const DragOverlayRow = memo(function DragOverlayRow({section}: {section: DashboardSectionConfig | undefined}) {
  if (!section) return null
  return (
    <div className={styles.row}>
      <DragAndDrop.DragTrigger />
      <div className={styles.rowText}>
        <span className={styles.rowLabel}>{section.name}</span>
        {section.description && <span className={styles.rowDescription}>{section.description}</span>}
      </div>
    </div>
  )
})

type DialogState = {order: string[]; hiddenSet: Set<string>}

// Builds the dialog's local order/hidden state from persisted preferences,
// filtering out unavailable sections and appending newly available ones.
function buildInitialState(
  initialOrder: string[],
  initialHidden: string[],
  availableSections: DashboardSectionConfig[],
): DialogState {
  const availableIds = new Set(availableSections.map(section => section.id))
  const hiddenSet = new Set(initialHidden.filter(id => availableIds.has(id)))
  const preferredOrder = initialOrder.length > 0 ? initialOrder : [...availableIds]

  // Keep ids that exist; append any newly-available ids to the end.
  const order = preferredOrder.filter(id => availableIds.has(id))
  const orderedIds = new Set(order)
  for (const id of availableIds) {
    if (!orderedIds.has(id)) order.push(id)
  }

  return {order, hiddenSet}
}

// Moves a visible section up or down relative to the next visible neighbor,
// while preserving hidden sections in their existing order slots.
function computeMoveVisible(state: DialogState, id: string, direction: -1 | 1): DialogState | null {
  // Walk `order` from the section's index in the chosen direction until we
  // land on the next visible id, then swap them in place. Hidden ids between
  // them keep their original `order` slots.
  const idIdx = state.order.indexOf(id)
  if (idIdx < 0) return null
  let neighbourIdx = idIdx + direction
  while (neighbourIdx >= 0 && neighbourIdx < state.order.length) {
    const candidate = state.order[neighbourIdx]
    if (candidate !== undefined && !state.hiddenSet.has(candidate)) break
    neighbourIdx += direction
  }
  if (neighbourIdx < 0 || neighbourIdx >= state.order.length) return null
  const next = [...state.order]
  const a = next[idIdx]
  const b = next[neighbourIdx]
  if (a === undefined || b === undefined) return null
  next[idIdx] = b
  next[neighbourIdx] = a
  return {order: next, hiddenSet: state.hiddenSet}
}

// Marks a section hidden when doing so would still leave at least one section visible.
function computeHideSection(state: DialogState, id: string): DialogState | null {
  if (state.hiddenSet.has(id)) return null
  // At least one section must remain visible.
  if (state.order.length - state.hiddenSet.size <= 1) return null
  const nextHidden = new Set(state.hiddenSet)
  nextHidden.add(id)
  return {order: state.order, hiddenSet: nextHidden}
}

// Restores a hidden section
function computeShowSection(state: DialogState, id: string): DialogState | null {
  if (!state.hiddenSet.has(id)) return null
  const nextHidden = new Set(state.hiddenSet)
  nextHidden.delete(id)
  return {order: state.order, hiddenSet: nextHidden}
}

// Reorders a dragged section around a visible drop target while keeping hidden ids in the order array.
function computeReorder(
  state: DialogState,
  draggedId: string,
  targetId: string,
  isBefore: boolean,
): DialogState | null {
  // Drops onto a hidden anchor or an unknown id are ignored.
  if (state.hiddenSet.has(targetId) || !state.order.includes(draggedId) || !state.order.includes(targetId)) {
    return null
  }
  const next: string[] = []
  for (const item of state.order) {
    if (item === draggedId) continue
    if (item === targetId) {
      if (isBefore) next.push(draggedId, item)
      else next.push(item, draggedId)
    } else {
      next.push(item)
    }
  }
  return {order: next, hiddenSet: state.hiddenSet}
}
